package com.xianshuyuan.scm.customer.controller;
import com.xianshuyuan.scm.common.api.ApiResponse;import com.xianshuyuan.scm.customer.dto.AgreementPriceSaveRequest;import com.xianshuyuan.scm.customer.service.AgreementPriceService;import com.xianshuyuan.scm.customer.vo.AgreementPriceResponse;import jakarta.validation.Valid;import jakarta.validation.constraints.Min;import org.springframework.web.bind.annotation.*;import java.util.List;
@RestController @RequestMapping("/api/agreement-prices") public class AgreementPriceController {private final AgreementPriceService service;public AgreementPriceController(AgreementPriceService s){service=s;}@GetMapping public ApiResponse<List<AgreementPriceResponse>> list(){return ApiResponse.success(service.list());}@PostMapping public ApiResponse<Long> create(@Valid @RequestBody AgreementPriceSaveRequest r){return ApiResponse.success(service.create(r));}@PutMapping("/{id}") public ApiResponse<Void> update(@PathVariable long id,@Valid @RequestBody AgreementPriceSaveRequest r){service.update(id,r);return ApiResponse.success(null);}@DeleteMapping("/{id}") public ApiResponse<Void> delete(@PathVariable long id,@RequestParam @Min(0) int version){service.delete(id,version);return ApiResponse.success(null);}}
